-- GASP dataset product_event (event; Product usage event). rows dated from 2025-12-01
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.product_event (
  customer_id VARCHAR(1000),
  event_date DATE,
  event_id VARCHAR(1000),
  feature_id VARCHAR(1000),
  product_event_type VARCHAR(1000),
  session_duration INTEGER,
  session_id VARCHAR(1000),
  signup_date DATE,
  usage_count INTEGER,
  user_id VARCHAR(1000)
);
